using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class FinishWalls {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));const string A="Assets/Afrer_Seconds/05.Model/Environment/";
 static Color Average(Texture t){if(!t)return Color.white;var rt=RenderTexture.GetTemporary(16,16,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear);var old=RenderTexture.active;var tex=new Texture2D(16,16,TextureFormat.RGB24,false,true);try{Graphics.Blit(t,rt);RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,16,16),0,0);tex.Apply();var c=tex.GetPixels();return new Color(c.Average(x=>x.r),c.Average(x=>x.g),c.Average(x=>x.b),1);}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(tex);RenderTexture.ReleaseTemporary(rt);}}
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");var original=SceneManager.GetActiveScene().path;AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(string f in Directory.GetFiles(A+"Common/Textures","WW_*.png")){var ti=(TextureImporter)AssetImporter.GetAtPath(f.Replace('\\','/'));ti.textureType=f.Contains("Normal")?TextureImporterType.NormalMap:TextureImporterType.Default;ti.sRGBTexture=f.Contains("Base");ti.wrapModeU=TextureWrapMode.Repeat;ti.wrapModeV=TextureWrapMode.Clamp;ti.mipmapEnabled=true;ti.maxTextureSize=2048;ti.anisoLevel=8;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();}var rows=new List<object>();try{foreach(string floor in new[]{"B5","B4"}){var s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+floor+"_Circular.unity");var backup=R+"/SourceAssets/B4_Finish/"+floor+"_walls_before.unity";if(!File.Exists(backup))EditorSceneManager.SaveScene(s,backup,true);var map=new Dictionary<Material,Material>();float ground=floor=="B5"?-82:-66;int serial=0;foreach(var rr in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>())){var mf=rr.GetComponent<MeshFilter>();if(!mf||!mf.sharedMesh)continue;string name=rr.name;if(!new[]{"Dome","Vault","Shell","Lining","PanelsRibs"}.Any(k=>name.Contains(k))||name.Contains("Pod")||name.Contains("Portal")||name.Contains("Door"))continue;var old=mf.sharedMesh;string oldPath=AssetDatabase.GetAssetPath(old);if(oldPath.Contains("/WW_"))throw new Exception("Wall already applied");var ms=rr.sharedMaterials;var eligible=Enumerable.Range(0,old.subMeshCount).Where(i=>i<ms.Length&&ms[i]&&!ms[i].name.Contains("Floor")&&(ms[i].name.Contains("Coat")||ms[i].name.Contains("Shell"))).ToHashSet();if(eligible.Count==0)continue;var vs=old.vertices;var ns=old.normals;var u=old.uv;var uv2=old.uv2;var nv=new List<Vector3>();var nn=new List<Vector3>();var nu=new List<Vector2>();var nu2=new List<Vector2>();var index=new Dictionary<long,int>();var sub=new List<int[]>();int changed=0;
 int Vertex(int vi,bool wall,int axis){long key=(long)vi*10+(wall?axis+1:0);if(index.TryGetValue(key,out var found))return found;int at=nv.Count;index[key]=at;nv.Add(vs[vi]);nn.Add(ns[vi]);var p=rr.transform.TransformPoint(vs[vi]);nu.Add(wall?new Vector2((axis==0?p.z:p.x)/6f+serial*.137f,Mathf.Max(.005f,p.y-ground)/4f):(u.Length==vs.Length?u[vi]:Vector2.zero));if(uv2.Length==vs.Length)nu2.Add(uv2[vi]);return at;}
 for(int i=0;i<old.subMeshCount;i++){var ix=old.GetTriangles(i);var dst=new int[ix.Length];for(int j=0;j<ix.Length;j+=3){var a=rr.transform.TransformPoint(vs[ix[j]]);var b=rr.transform.TransformPoint(vs[ix[j+1]]);var c=rr.transform.TransformPoint(vs[ix[j+2]]);var n=Vector3.Cross(b-a,c-a).normalized;bool wall=eligible.Contains(i);int axis=Mathf.Abs(n.x)>Mathf.Abs(n.z)?0:1;for(int k=0;k<3;k++)dst[j+k]=Vertex(ix[j+k],wall,axis);if(wall)changed++;}sub.Add(dst);if(eligible.Contains(i)){var source=ms[i];if(!map.TryGetValue(source,out var m)){string path=A+floor+"/Materials/WW_"+floor+"_"+source.name+".mat";m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(source){name="WW_"+floor+"_"+source.name};var col=source.GetColor("_BaseColor");var avg=Average(source.GetTexture("_BaseMap"));m.SetColor("_BaseColor",new Color(col.r*avg.r/.887f,col.g*avg.g/.887f,col.b*avg.b/.887f,col.a));AssetDatabase.CreateAsset(m,path);}m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(A+"Common/Textures/WW_"+floor+"_Base.png"));m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(A+"Common/Textures/WW_"+floor+"_Normal.png"));m.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(A+"Common/Textures/WW_"+floor+"_MetalSmooth.png"));m.SetTextureScale("_BaseMap",Vector2.one);m.SetTextureOffset("_BaseMap",Vector2.zero);m.SetFloat("_BumpScale",.24f);m.SetFloat("_Smoothness",1);m.SetFloat("_Metallic",1);m.EnableKeyword("_NORMALMAP");m.EnableKeyword("_METALLICSPECGLOSSMAP");m.enableInstancing=true;map[source]=m;EditorUtility.SetDirty(m);}ms[i]=m;}}
 if(changed==0)continue;var mesh=new Mesh{name="WW_"+floor+"_Wall_"+(++serial).ToString("000"),indexFormat=nv.Count>65535?IndexFormat.UInt32:IndexFormat.UInt16};mesh.SetVertices(nv);mesh.SetNormals(nn);mesh.SetUVs(0,nu);if(nu2.Count>0)mesh.SetUVs(1,nu2);mesh.subMeshCount=sub.Count;for(int i=0;i<sub.Count;i++)mesh.SetTriangles(sub[i],i,false);mesh.RecalculateBounds();mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,A+floor+"/"+mesh.name+".asset");mf.sharedMesh=mesh;rr.sharedMaterials=ms;PrefabUtility.RecordPrefabInstancePropertyModifications(mf);PrefabUtility.RecordPrefabInstancePropertyModifications(rr);rows.Add(new{floor,name=rr.name,id=GlobalObjectId.GetGlobalObjectIdSlow(rr).ToString(),oldPath,oldMesh=old.name,newPath=AssetDatabase.GetAssetPath(mesh),changedTriangles=changed,oldTriangles=old.triangles.Length/3,newTriangles=mesh.triangles.Length/3});}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}AssetDatabase.SaveAssets();}finally{EditorSceneManager.OpenScene(original);}File.WriteAllText(R+"/SourceAssets/B4_Finish/walls_applied.json",JsonConvert.SerializeObject(rows,Formatting.Indented));return new{renderers=rows.Count};}
}
